// AJUSTAR CONFORME O PAYLOAD REAL DA UAZAPI (não foi possível confirmar os nomes exatos
// de campo neste ambiente - o acesso à documentação da UAZAPI está bloqueado aqui).
// Modelo assumido, comum em APIs baseadas em Baileys (mesma família da Evolution API):
// {
//   "event": "messages.upsert",
//   "instance": "minha-instancia",
//   "data": {
//     "key": { "remoteJid": "5511999999999@s.whatsapp.net", "fromMe": false, "id": "ABC123" },
//     "pushName": "João Silva",
//     "message": { "conversation": "Oi, tudo bem?" }
//   }
// }
const body = $json.body || {};
const data = body.data || body;
const key = data.key || {};

const remoteJid = key.remoteJid || data.chatid || data.phone || '';
const phone = String(remoteJid).replace('@s.whatsapp.net', '').replace('@g.us', '');

const text =
  data?.message?.conversation ||
  data?.message?.extendedTextMessage?.text ||
  data?.text ||
  data?.body ||
  '';

const fromMe = Boolean(key.fromMe ?? data.fromMe ?? false);
const externalId = key.id || data.id || null;
const pushName = data.pushName || data.senderName || null;

return [{
  json: {
    phone,
    text: String(text).trim(),
    fromMe,
    externalId,
    pushName,
  }
}];

// Decide se, à primeira vista, é plausível ser um assunto novo (usado depois,
// na hora de responder). Regra: se o lead falou há pouco tempo (ex.: dentro de
// 6h), é claramente a mesma conversa. Só quando o intervalo é grande (ex.: o
// caso de retornar 7 dias depois) é que vale a pena perguntar à IA se é
// continuação ou assunto novo.
const LIMITE_HORAS_MESMO_ASSUNTO = 6;

const rows = $input.all();
const atendimentoAnterior = rows.length > 0 ? rows[0].json : null;

let gapHoras = null;
let possivelNovoAssunto = true;

if (atendimentoAnterior) {
  const last = new Date(atendimentoAnterior.last_message_at);
  gapHoras = (Date.now() - last.getTime()) / (1000 * 60 * 60);
  possivelNovoAssunto = gapHoras > LIMITE_HORAS_MESMO_ASSUNTO;
}

return [{
  json: {
    temAtendimentoAnterior: !!atendimentoAnterior,
    atendimentoAnteriorId: atendimentoAnterior ? atendimentoAnterior.id : null,
    topicoAnterior: atendimentoAnterior ? atendimentoAnterior.topico : null,
    resumoAnterior: atendimentoAnterior ? atendimentoAnterior.resumo : null,
    classificacaoAnterior: atendimentoAnterior ? atendimentoAnterior.classificacao : null,
    gapHoras,
    possivelNovoAssunto,
  }
}];

