const ctx = $('Preparar Contexto e Calcular Gap').item.json;
const mensagemConsolidada = $('Montar Texto Consolidado').item.json.mensagemConsolidada;
const saida = $json.output;

let reutilizarAtendimento = false;
if (ctx.temAtendimentoAnterior) {
  reutilizarAtendimento = ctx.possivelNovoAssunto ? saida.mesmo_assunto === true : true;
}

return [{
  json: {
    ...ctx,
    mensagemConsolidada,
    ...saida,
    reutilizarAtendimento,
  }
}];

