// Quebra a resposta da IA (já vem fatiada em bolhas) em vários ITENS,
// um por bolha, para percorrer no loop de "digitando + enviar" logo abaixo.
// O tempo de "digitando" é estimado pelo tamanho do texto, simulando uma
// velocidade de digitação humana (limitado entre 1.2s e 4.5s por bolha).
const mensagens = $('Decidir Atendimento (novo ou continuar)').item.json.mensagens_resposta || [];
const atendimentoId = $json.atendimento_id;
const phone = $('Normalizar Payload UAZAPI').item.json.phone;

function calcularDelaySegundos(texto) {
  const base = 1.0;
  const segundosPorCaractere = 0.03;
  const bruto = base + texto.length * segundosPorCaractere;
  return Math.min(Math.max(bruto, 1.2), 4.5);
}

return mensagens.map((texto) => ({
  json: {
    texto,
    delaySegundos: calcularDelaySegundos(texto),
    atendimentoId,
    phone,
  },
}));

// AJUSTAR: extrai o ID retornado pela UAZAPI para esta bolha específica,
// para reconhecer o eco dela no webhook e não disparar handoff sozinho.
const resposta = $json;
const externalId = resposta.id || resposta?.key?.id || resposta?.messageId || null;
const itemDoLoop = $('Loop Mensagens Picadas').item.json;

return [{
  json: {
    texto: itemDoLoop.texto,
    atendimentoId: itemDoLoop.atendimentoId,
    externalId,
  },
}];
